tool_input.command:
cd src/styles && python - <<'EOF' 2>/dev/null || node -e "
const fs=require('fs');let s=fs.readFileSync('base.css','utf8');
s=s.replace(/  font-size: 7px;
  font-weight: var\(--font-weight-semibold\);
  letter-spacing: 0;/,'  font-size: var(--font-size-micro);
  font-weight: var(--font-weight-semibold);
  letter-spacing: -0.04em;');
s=s.replace(/  width: 20px;
  height: 20px;
  font-size: 8px;/,'  width: 20px;
  height: 20px;');
fs.writeFileSync('base.css',s);"
EOF
